const input = $json;
const weather = input.weather;
const hourly = weather?.hourly;
if (!input.cityData?.name || !weather?.current || !Array.isArray(hourly?.time) || !hourly.time.length) {
  throw new Error('Open-Meteo response is missing current weather or hourly forecast data.');
}

const requiredHourlyFields = ['temperature_2m', 'precipitation_probability', 'wind_speed_10m'];
if (requiredHourlyFields.some((field) => !Array.isArray(hourly[field]) || hourly[field].length !== hourly.time.length)) {
  throw new Error('Open-Meteo returned incomplete hourly forecast data.');
}

const dateParts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
}).formatToParts(new Date()).reduce((result, part) => {
  if (part.type !== 'literal') result[part.type] = part.value;
  return result;
}, {});
const currentLocalTime = `${dateParts.year}-${dateParts.month}-${dateParts.day}T${dateParts.hour}:${dateParts.minute}`;
const nextHours = hourly.time.map((time, index) => ({ time, index })).filter((hour) => hour.time > currentLocalTime).slice(0, 24);
if (nextHours.length !== 24) {
  throw new Error(`Expected 24 future hourly readings, received ${nextHours.length}.`);
}
const temperatures = nextHours.map(({ index }) => Number(hourly.temperature_2m[index]));
const rain = nextHours.map(({ index }) => Number(hourly.precipitation_probability[index] ?? 0));
if (temperatures.some((value) => !Number.isFinite(value)) || rain.some((value) => !Number.isFinite(value))) {
  throw new Error('Open-Meteo returned invalid hourly temperature or precipitation data.');
}
const maxTemp = Math.max(...temperatures);
const minTemp = Math.min(...temperatures);
const maxRain = Math.max(...rain);
const weatherCode = Number(weather.current.weather_code);
const weatherArabic = (code) => {
