  if (code === 1) return '?????? ????';
  if (code === 2) return '???? ??????';
  if (code === 3) return '????';
  if (code === 45 || code === 48) return '????';
  if ([51, 53, 55, 56, 57].includes(code)) return '????';
  if ([61, 63, 65, 66, 67, 80, 81, 82].includes(code)) return '???';
  if ([71, 73, 75, 77, 85, 86].includes(code)) return '???';
  if ([95, 96, 99].includes(code)) return '????? ?????';
  return '??? ?????';
};

const best = nextHours.reduce((choice, hour) => {
  const temperature = Number(hourly.temperature_2m[hour.index]);
  const precipitation = Number(hourly.precipitation_probability[hour.index] ?? 0);
  const wind = Number(hourly.wind_speed_10m[hour.index] ?? 0);
  const score = precipitation * 2 + Math.abs(temperature - 22) + Math.max(0, wind - 20) * 0.5;
  return !choice || score < choice.score ? { ...hour, score } : choice;
}, null);
const bestHour = best.time.slice(11, 16);
let recommendation;
if (maxRain >= 50) recommendation = '?? ????? ?????? ????? ????? ???? ??????? ???????.';
else if (maxTemp >= 33) recommendation = '???? ?????? ??? ??????? ???? ????.';
else if (minTemp <= 12) recommendation = '???? ?????? ?????? ?? ??????? ???????.';
else recommendation = `????? ?????? ???? ??? ????? ${bestHour}.`;

return { json: {
  ...input,
  code_city: input.cityData.name,
  code_temperature_now_c: Number(weather.current.temperature_2m),
  code_weather_ar: weatherArabic(weatherCode),
  code_max_temperature_c: maxTemp,
  code_min_temperature_c: minTemp,
  code_max_rain_probability: maxRain,
  code_best_hour: bestHour,
  code_recommendation: recommendation
} };

return { json: {
